/**
 * Cross-runtime goldens, direction 2 (rust-cli node-store W2, specs/fork-rust-workflow-engine.md §5.1, §8).
 *
 * The scenario in `packages/rust-cli/crates/node-store/fixtures/dwf/scenario.json` is written by the Rust
 * repository into `rust-written.sqlite` (regenerated by `regenerate_rust_written_golden`), and by Node into
 * `node-written.sqlite` (`scripts/rust-cli/dwf-journal-goldens.ts`). Node's own readers must return the
 * same records from the Rust-written file as `node-expected.json` records (which Node produced from its
 * own file). Timestamps are not compared.
 */
import { copyFileSync, mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { DatabaseSync } from "node:sqlite";
import { afterAll, describe, expect, it } from "vitest";
import { createDwfJournalStore } from "../src/storage/session-store/repositories/dwf-journal.js";

const fixtures = fileURLToPath(
  new URL("../../../../../packages/rust-cli/crates/node-store/fixtures/dwf/", import.meta.url),
);
const expected = JSON.parse(readFileSync(join(fixtures, "node-expected.json"), "utf8")) as Record<
  string,
  unknown
>;
const ALL_EVENTS = { types: "all", reportItems: "all" } as const;
const workDirs: string[] = [];

afterAll(() => {
  for (const dir of workDirs) rmSync(dir, { recursive: true, force: true });
});

/** Opens a private copy, so a read never touches the fixture itself. */
function openCopy(fixture: string): DatabaseSync {
  const dir = mkdtempSync(join(tmpdir(), "dwf-golden-"));
  workDirs.push(dir);
  const copy = join(dir, "journal.sqlite");
  copyFileSync(join(fixtures, fixture), copy);
  return new DatabaseSync(copy);
}

/** Reads every golden surface with Node's readers, in the shape of `node-expected.json`. */
function readWithNode(fixture: string): Record<string, unknown> {
  const db = openCopy(fixture);
  try {
    const journal = createDwfJournalStore(db) as ReturnType<typeof createDwfJournalStore> & {
      listNonTerminalRuns(parentSessionId: string): unknown[];
    };
    const runIds = expected.runIds as string[];
    const actors: Record<string, unknown> = {};
    const nodes: Record<string, unknown> = {};
    const events: Record<string, unknown> = {};
    for (const runId of runIds) {
      actors[runId] = journal.listActors(runId, { withPersona: true });
      nodes[runId] = journal.listNodes(runId, { kinds: "all", withResult: true });
      events[runId] = journal
        .listEvents(runId, ALL_EVENTS)
        .map(({ sequence, event }) => ({ sequence, event }));
    }
    const taskLinks = db
      .prepare(
        `select id, root_workflow_run_id, parent_link_id, activity_id, parent_session_id, child_session_id,
                role, depth, path, phase, label, agent_type, model, status
         from session_task_link order by id`,
      )
      .all();
    const ledger = db
      .prepare("select checksum from schema_migration where id = '0019_dwf_journal'")
      .get() as { checksum: string };
    return JSON.parse(
      JSON.stringify({
        runIds,
        runs: runIds.map((runId) => journal.getRun(runId)),
        actors,
        nodes,
        events,
        nonTerminalByParent: { sess_parent: journal.listNonTerminalRuns("sess_parent") },
        taskLinks,
        checksums: { "0019_dwf_journal": ledger.checksum },
      }),
    ) as Record<string, unknown>;
  } finally {
    db.close();
  }
}

describe("dwf_* goldens: Node reads what Rust wrote", () => {
  it("returns the node-expected records from the Rust-written database", () => {
    const actual = readWithNode("rust-written.sqlite");
    for (const key of Object.keys(expected)) {
      expect(actual[key], `golden surface ${key}`).toEqual(expected[key]);
    }
  });

  it("reads the Node-written database to the same records (the reader reference)", () => {
    const actual = readWithNode("node-written.sqlite");
    expect(actual).toEqual(expected);
  });

  it("pins the 0019 ledger checksum to the upstream value", () => {
    // fork-upstream-migrations.json, cli set (specs/upstream-migration-freeze.md).
    expect((expected.checksums as Record<string, string>)["0019_dwf_journal"]).toBe(
      "1c8da5568d2357f25c392be486fae80e1f3ad3ebc830dab1bee941634573e8ba",
    );
  });
});
